import {
  Component,
  ElementRef,
  afterNextRender,
  computed,
  inject,
  input,
  viewChild,
  type InputSignal,
  type Signal,
} from '@angular/core';

import { CwKbd } from '@cadenway/ui/components/kbd';

import { KANBAN_BOARD, type KanbanBoard, type KanbanCellView } from '../kanban.token';

/**
 * Component KanbanQuickAddPart
 *
 * @description
 * The quick add of `cw-kanban`, generated by the board at the bottom of a column (or of a cell in swimlanes) when « + », « Ajouter une tâche » or N opens it: a form with one borderless field and the « Entrée créer » hint. Enter emits the board's `created` with the trimmed title and keeps the field open, empty, for the next one; Escape closes it and the focus returns to the column. The field takes the focus when it opens.
 */
@Component({
  selector: 'cw-kanban-quick-add',
  imports: [CwKbd],
  host: { class: 'block' },
  templateUrl: './kanban-quick-add.component.html',
})
export class KanbanQuickAddPart {
  // #region Properties
  /**
   * Property cell
   *
   * @description
   * The cell the new card goes to.
   *
   * @type {InputSignal<KanbanCellView>}
   * @readonly
   */
  public readonly cell: InputSignal<KanbanCellView> = input.required<KanbanCellView>();

  /**
   * Property board
   *
   * @description
   * Board state and handlers exposed to this part.
   *
   * @type {KanbanBoard}
   * @readonly
   */
  protected readonly board: KanbanBoard = inject(KANBAN_BOARD);

  /**
   * Property field
   *
   * @description
   * Quick-add text input.
   *
   * @type {Signal<ElementRef<HTMLInputElement>>}
   * @readonly
   */
  private readonly field: Signal<ElementRef<HTMLInputElement>> =
    viewChild.required<ElementRef<HTMLInputElement>>('field');

  /**
   * Property formLabel
   *
   * @description
   * Accessible label of the quick-add form.
   *
   * @type {Signal<string>}
   * @readonly
   */
  protected readonly formLabel: Signal<string> = computed(() =>
    this.board.format(this.board.texts().quickAdd, { column: this.cell().column.label }),
  );
  // #endregion

  // #region Constructor
  /**
   * Constructor
   *
   * @description
   * Focuses the quick-add field after rendering.
   *
   * @constructor
   */
  public constructor() {
    afterNextRender(() => {
      this.field().nativeElement.focus();
    });
  }
  // #endregion

  // #region Methods
  /**
   * Method submit
   *
   * @description
   * Submits the quick-add field.
   *
   * @param {Event} event - Mouse, keyboard, drag or form event.
   */
  protected submit(event: Event): void {
    event.preventDefault();
    const field: HTMLInputElement = this.field().nativeElement;
    this.board.create(field.value, this.cell());
    field.value = '';
  }

  /**
   * Method close
   *
   * @description
   * Closes the quick-add form.
   *
   * @param {Event} event - Mouse, keyboard, drag or form event.
   */
  protected close(event: Event): void {
    event.preventDefault();
    event.stopPropagation();
    this.board.closeQuickAdd(this.cell());
  }
  // #endregion
}
